def bars(groups,rows):
    c=['#9aa6bd','#2b5be0']
    h='<div class="bars"><div class="k">'+''.join(f'<span style="--c:{c[i]}">{g}</span>' for i,g in enumerate(groups))+'</div>\n'
    for name,*v in rows:
        h+=f'<p class="q">{name}</p>'+''.join(f'<div class="row"><div class="t"><b style="width:{x}%;background:{c[i]}"></b></div><div class="v">{x}%</div></div>' for i,x in enumerate(v))+'\n'
    return h+'</div>\n'
